class Solution:
    def divide(self, dividend, divisor):
        dividend, divisor = abs(dividend), abs(divisor)
        quotient = 0
        while dividend >= divisor:
            value = divisor
            multiple = 1
            while dividend >= (value << 1):
                value <<= 1
                multiple <<= 1
            dividend -= value
            quotient += multiple
        return quotient

class Solution:
    def smallestStableIndex(self, nums):
        n = len(nums)
        total = sum(nums)
        best = -1
        for i in range(n):
            if max(nums[i:]) <= total - nums[i]:
                if best == -1:
                    best = i
        return best

class Solution:
    def constructUniformParityArray(self, nums):
        candidate = -1
        for x in nums:
            if x % 2 == 1:
                candidate = x
                break
        if candidate == -1:
            return []
        for i in range(len(nums)):
            if nums[i] % 2 == 0:
                nums[i] = candidate
        return nums

class Solution:
    def constructUniformParityArray(self, nums):
        candidate = -1
        for x in nums:
            if x % 2 == 1 and x > candidate:
                candidate = x
        for i in range(len(nums)):
            if nums[i] % 2 == 0:
                nums[i] = candidate
        return nums

class Solution:
    def moveZeroes(self, nums):
        left = 0
        for right in range(len(nums)):
            if nums[right] != 0:
                nums[left], nums[right] = nums[right], nums[left]
                left += 1

class Solution:
    def twoSum(self, numbers, target):
        left = 0
        right = len(numbers) - 1
        while left < right:
            cur = numbers[left] + numbers[right]
            if cur == target:
                return [left + 1, right + 1]
            elif cur < target:
                left += 1
            else:
                right -= 1
        return []

class Solution:
    def minSubArrayLen(self, target, nums):
        left = 0
        total = 0
        best = float('inf')
        for right in range(len(nums)):
            total += nums[right]
            while total >= target:
                best = min(best, right - left + 1)
                total -= nums[left]
                left += 1
        return best if best != float('inf') else 0

class Solution:
    def hasCycle(self, head):
        slow = head
        fast = head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
            if slow == fast:
                return True
        return False
